            q("q1", f"SELECT {ACTIVITY_FAMILY} AS activity_family, COUNT(*) AS company_count FROM finance WHERE principal_activities != '' GROUP BY activity_family", "How many companies are primarily in finance, healthcare, technology, retail, mining, or another activity?"),
