            q("q7", f"SELECT {AUDITOR_FAMILY} AS auditor_family, AVG(total_assets) AS avg_assets FROM finance WHERE auditor != '' AND total_assets IS NOT NULL GROUP BY auditor_family", "What is the average total assets of companies audited by EY, KPMG, PwC, Deloitte, or another firm?"),
